public sealed record RemoteBridgePreview(string Source,string Destination,long Size,DateTime SourceModified,bool DestinationExists,long? DestinationSize,DateTime? DestinationModified,long? AvailableBytes,int MemoryBufferBytes=65536,long TemporaryDiskBytes=0);
public sealed partial class SshSession
{
 bool SameBridgePath(SshSession destination,string source,string target)=>source==target&&(ReferenceEquals(this,destination)||(Profile.Protocol=="native"?destination.Profile.Protocol=="native"&&Profile.Native.Target==destination.Profile.Native.Target&&Profile.Native.Port==destination.Profile.Native.Port&&Profile.Username==destination.Profile.Username:destination.Profile.Protocol!="native"&&Profile.Host.Equals(destination.Profile.Host,StringComparison.OrdinalIgnoreCase)&&Profile.Port==destination.Profile.Port&&Profile.Username==destination.Profile.Username));
 static void BridgePath(string path){if(string.IsNullOrWhiteSpace(path)||path.Length>4096||!path.StartsWith('/')||path.Any(char.IsControl)||path.Split('/').Any(part=>part is "." or ".."))throw new ArgumentException("Percorso remoto assoluto non valido.");}
 static void BridgeParents(SftpClient channel,string path){var parts=path.Split('/',StringSplitOptions.RemoveEmptyEntries);var current="/";if(parts.Length>64)throw new IOException("Percorso remoto troppo profondo.");foreach(var part in parts.SkipLast(1)){current=current.TrimEnd('/')+"/"+part;var item=channel.Get(current);if(item.IsSymbolicLink||!item.IsDirectory)throw new IOException("Una cartella remota è collegata o non disponibile.");}}
 static void BridgeFile(SftpClient channel,string path){BridgeParents(channel,path);var item=channel.Get(path);if(item.IsSymbolicLink||!item.IsRegularFile)throw new IOException("Seleziona un file normale, senza collegamenti simbolici.");}
 public async Task<RemoteBridgePreview> BridgePreflightAsync(SshSession destination,string sourcePath,string targetPath,CancellationToken ct=default){
  BridgePath(sourcePath);BridgePath(targetPath);if(targetPath.Length>4000)throw new ArgumentException("Percorso di destinazione troppo lungo.");if(SameBridgePath(destination,sourcePath,targetPath))throw new IOException("Sorgente e destinazione coincidono.");using var from=await FileChannel(ct);using var to=await destination.FileChannel(ct);using var stop=ct.Register(()=>{from.Dispose();to.Dispose();});try{return await Task.Run(()=>{ct.ThrowIfCancellationRequested();BridgeFile(from,sourcePath);BridgeParents(to,targetPath);var source=from.GetAttributes(sourcePath);var exists=to.Exists(targetPath);if(exists)BridgeFile(to,targetPath);long? available=null;try{var parent=targetPath[..targetPath.LastIndexOf('/')];var space=to.GetStatus(parent.Length==0?"/":parent);if(space.IsReadOnly)throw new IOException("La destinazione remota è in sola lettura.");available=CapacityBytes(space.AvailableBlocks,space.BlockSize);}catch(Exception error)when(!ct.IsCancellationRequested&&error is SshException or NotSupportedException){}ct.ThrowIfCancellationRequested();return new RemoteBridgePreview(sourcePath,targetPath,source.Size,source.LastWriteTimeUtc,exists,exists?to.GetAttributes(targetPath).Size:null,exists?to.GetAttributes(targetPath).LastWriteTimeUtc:null,available);},ct);}catch(Exception)when(ct.IsCancellationRequested){throw new OperationCanceledException(ct);}
 }
 public async Task<bool> BridgeTransferAsync(SshSession destination,string sourcePath,TransferRequest request,Action<ulong,long> progress,CancellationToken ct,Action<TransferCheckpoint>? checkpointObserved=null){
  BridgePath(sourcePath);BridgePath(request.Remote);if(request.Remote.Length>4000)throw new ArgumentException("Percorso di destinazione troppo lungo.");if(!Guid.TryParse(request.Id,out _)||!request.Upload||request.Directory||request.CreateParents||request.AutomaticRecovery||request.Permissions!=null||request.ExpectedHash!=null||request.ExpectedSourceHash!=null||request.ExpectedMissingTarget||request.WindowStartMinute!=null||request.WindowEndMinute!=null||request.Conflict is not("new" or "replace")||request.BandwidthKiB is <0 or >1048576)throw new ArgumentException("Trasferimento tra server non valido.");if(SameBridgePath(destination,sourcePath,request.Remote))throw new IOException("Sorgente e destinazione coincidono.");
  using var from=await FileChannel(ct);using var to=await destination.FileChannel(ct);using var stop=ct.Register(()=>{from.Dispose();to.Dispose();});try{return await Task.Run(()=>{
   ct.ThrowIfCancellationRequested();BridgeFile(from,sourcePath);BridgeParents(to,request.Remote);var sourceAttributes=from.GetAttributes(sourcePath);using var source=from.OpenRead(sourcePath);var size=source.Length;if(size<0||size>request.MaximumSourceBytes)throw new IOException("Sorgente oltre il limite del trasferimento.");var sourceHash=CheckpointHash(source,ct,size);source.Position=0;
   TransferFileVersion? Target(){if(!to.Exists(request.Remote))return null;BridgeFile(to,request.Remote);var info=to.GetAttributes(request.Remote);if(info.Size<0)throw new IOException("Dimensione remota non valida.");using var stream=to.OpenRead(request.Remote);return new(info.Size,info.LastWriteTimeUtc,CheckpointHash(stream,ct,info.Size));}
   var target=Target();if(target!=null&&request.Conflict=="new")throw new IOException("La destinazione esiste. Nessun file è stato sostituito.");var checkpoint=new TransferCheckpoint(new(size,sourceAttributes.LastWriteTimeUtc,sourceHash),target);if(request.Resume)request.Checkpoint?.Validate(checkpoint);checkpointObserved?.Invoke(request.Checkpoint??checkpoint);
   var partial=request.Remote+".relay-"+request.Id+".partial";long offset=0;var partialExists=to.Exists(partial);if(partialExists){if(!request.Resume||request.Checkpoint==null)throw new IOException("File parziale già presente: ripresa verificata richiesta.");BridgeFile(to,partial);using var prefix=to.OpenRead(partial);offset=prefix.Length;if(offset<0||offset>size)throw new IOException("Il file parziale supera la sorgente.");VerifyPrefix(source,prefix,offset,ct);}
   try{var parent=request.Remote[..request.Remote.LastIndexOf('/')];var space=to.GetStatus(parent.Length==0?"/":parent);if(space.IsReadOnly)throw new IOException("La destinazione è in sola lettura.");var available=CapacityBytes(space.AvailableBlocks,space.BlockSize);if(available is{} bytes&&bytes<size-offset)throw new IOException("Spazio insufficiente sul server di destinazione.");}catch(Exception error)when(!ct.IsCancellationRequested&&error is SshException or NotSupportedException){}
   var buffer=new byte[65536];try{using(var output=to.Open(partial,partialExists?FileMode.Open:FileMode.CreateNew,FileAccess.Write)){to.ChangePermissions(partial,600);source.Position=offset;output.Position=offset;long done=offset;progress((ulong)done,size);var watch=System.Diagnostics.Stopwatch.StartNew();int read;while((read=source.Read(buffer,0,buffer.Length))>0){ct.ThrowIfCancellationRequested();if(read>size-done)throw new IOException("La sorgente è cambiata durante il trasferimento.");output.Write(buffer,0,read);done+=read;progress((ulong)done,size);if(request.BandwidthKiB>0){var delay=TimeSpan.FromSeconds((done-offset)/(request.BandwidthKiB*1024d))-watch.Elapsed;if(delay>TimeSpan.Zero&&ct.WaitHandle.WaitOne(delay))ct.ThrowIfCancellationRequested();}}output.Flush();if(done!=size)throw new IOException("La sorgente è cambiata durante il trasferimento.");}}finally{CryptographicOperations.ZeroMemory(buffer);}
   ct.ThrowIfCancellationRequested();BridgeFile(to,partial);using(var staged=to.OpenRead(partial))if(CheckpointHash(staged,ct,size)!=sourceHash)throw new IOException("Verifica del file trasferito non riuscita. La destinazione originale è conservata.");var after=from.GetAttributes(sourcePath);if(after.Size!=size||after.LastWriteTimeUtc!=sourceAttributes.LastWriteTimeUtc)throw new IOException("La sorgente è cambiata. Il file originale di destinazione è conservato.");checkpoint.Validate(new(new(size,sourceAttributes.LastWriteTimeUtc,sourceHash),Target()));ct.ThrowIfCancellationRequested();
   if(target!=null){var original=to.GetAttributes(request.Remote);var own=to.GetAttributes(partial);own.OwnerCanRead=original.OwnerCanRead;own.OwnerCanWrite=original.OwnerCanWrite;own.OwnerCanExecute=original.OwnerCanExecute;own.GroupCanRead=original.GroupCanRead;own.GroupCanWrite=original.GroupCanWrite;own.GroupCanExecute=original.GroupCanExecute;own.OthersCanRead=original.OthersCanRead;own.OthersCanWrite=original.OthersCanWrite;own.OthersCanExecute=original.OthersCanExecute;to.SetAttributes(partial,own);}to.RenameFile(partial,request.Remote,target!=null);progress((ulong)size,size);return true;
  },ct);}catch(Exception)when(ct.IsCancellationRequested){throw new OperationCanceledException(ct);}
 }
